  var composer=ta.closest(".msg-composer"); if(composer){ composer.addEventListener("dragover",function(e){ if(e.dataTransfer&&e.dataTransfer.types&&Array.prototype.indexOf.call(e.dataTransfer.types,"Files")>=0){ e.preventDefault(); composer.classList.add("dragging"); } }); composer.addEventListener("dragleave",function(e){ if(!composer.contains(e.relatedTarget))composer.classList.remove("dragging"); }); composer.addEventListener("drop",function(e){ var files=Array.prototype.slice.call((e.dataTransfer&&e.dataTransfer.files)||[]).filter(function(f){return /^image\//.test(f.type)||/^video\//.test(f.type);}); composer.classList.remove("dragging"); if(files.length){e.preventDefault();files.forEach(msgStageFile);} }); }
