function msgCaretAnchor(ta){ var wrap=ta.closest(".msg-input")||ta; return {contains:function(n){ return wrap.contains(n); },getBoundingClientRect:function(){ var r=ta.getBoundingClientRect(); var x=r.left; try{ var m=document.createElement("div"), cs=getComputedStyle(ta); ["font","fontSize","fontFamily","lineHeight","padding","letterSpacing","whiteSpace","wordWrap","width","boxSizing"].forEach(function(k){ m.style[k]=cs[k]; }); m.style.position="absolute"; m.style.visibility="hidden"; m.style.whiteSpace="pre-wrap"; m.style.width=ta.clientWidth+"px"; m.textContent=ta.value.slice(0,ta.selectionStart).replace(/@[^\s@]*$/,""); var sp=document.createElement("span"); sp.textContent="@"; m.appendChild(sp); document.body.appendChild(m); x=Math.min(r.left+sp.offsetLeft,r.right-40); m.remove(); }catch(e){} var w=wrap.getBoundingClientRect(); return {left:x,right:x+1,top:w.top,bottom:w.bottom,width:1,height:w.height}; }}; }
function msgCaretMention(ta){ var v=ta.value.slice(0,ta.selectionStart), m=v.match(/(?:^|\s)@([^\s@]*)$/); return m?m[1]:null; }
function msgOpenMention(ta,q){ var c=conv(S.messageConversationId); CHAT_RUNTIME.mentionOpen=true; entityPicker({kind:"person",anchor:msgCaretAnchor(ta),align:"left",initial:q,placeholder:tr("Mention someone…"),context:{members:convMembers(c),everyone:has("mention_everyone")||has("manage_teams")||c.type==="GROUP"||c.type==="DM"},onSelect:function(id){ msgInsertMention(id); },onClose:function(){ CHAT_RUNTIME.mentionOpen=false; var t=document.getElementById("msgInput"); if(t) t.focus(); }}); var ep=document.getElementById("entityPicker"); if(ep){ ep.classList.add("ep-mention"); var s=ep.querySelector(".ep-search"); if(s) s.setAttribute("tabindex","-1"); setTimeout(function(){ ta.focus(); },20); } }
function msgMentionButton(){ var ta=document.getElementById("msgInput"); if(!ta) return; ta.focus(); var v=ta.value, pos=ta.selectionStart; var ins=(pos>0&&!/\s$/.test(v.slice(0,pos))?" ":"")+"@"; ta.setRangeText(ins,pos,pos,"end"); ta.dispatchEvent(new Event("input")); }
function msgInsertMention(id){ var ta=document.getElementById("msgInput"), c=conv(S.messageConversationId); if(!ta) return; var display=id==="@everyone"?"everyone":person(id).name; var before=ta.value.slice(0,ta.selectionStart).replace(/@[^\s@]*$/,""), after=ta.value.slice(ta.selectionStart); ta.value=before+"@"+display+" "+after; var d=msgDraft(c.id); d.text=ta.value; if(!d.mentions.some(function(x){ return x.userId===id; })) d.mentions.push({userId:id,display:display}); var p=before.length+display.length+2; ta.setSelectionRange(p,p); CHAT_RUNTIME.mentionOpen=false; epClose(); ta.focus(); ta.dispatchEvent(new Event("input")); if(typeof WorkspaceQuest!=="undefined") WorkspaceQuest.emit("messages-mention"); }
