function msgStageRef(ref){ var c=conv(S.messageConversationId), d=msgDraft(c.id), links=ref.type==="URL"||ref.type==="DRIVE_LINK", used=d.refs.filter(function(r){return r.type!=="URL"&&r.type!=="DRIVE_LINK";}).length; if((links&&d.refs.length>=MSG_MAX_REFS)||(!links&&used>=MSG_MAX_ATTACH)) return toast(tr("Up to")+" "+(links?MSG_MAX_REFS:MSG_MAX_ATTACH)+" "+tr(links?"links per message":"attachments per message"),"bad"); if(d.refs.some(function(r){ return r.type===ref.type&&(r.entityId&&r.entityId===ref.entityId||r.url&&r.url===ref.url); })) return; d.refs.push(ref); CHAT_RUNTIME.focusComposer=true; renderMsgMain(true); }
