function msgUploadRef(ref,file){ ref.uploadState="pending"; ref.localFile=file; uploadAny(file,{forceDrive:!!msgMediaKind(file.type)}).then(function(r){ Object.assign(ref,{name:r.name||file.name,size:r.size,fileType:r.type,mimeType:file.type||r.mime||"",mediaKind:msgMediaKind(file.type||r.mime,r.type),url:r.url||"",driveId:r.driveId||null,preview:r.preview||ref.preview||"",source:r.source,temporary:!!r.temporary,uploadState:"ready"}); delete ref.localFile; if(S.screen==="messages"&&S.messageConversationId)renderMsgMain(true); }).catch(function(e){ ref.uploadState="failed"; ref.uploadError=e.message; if(S.screen==="messages")renderMsgMain(true); }); }
function msgStageFile(file){ var c=conv(S.messageConversationId); if(!c||!file)return; var d=msgDraft(c.id), used=d.refs.filter(function(r){return r.type!=="URL"&&r.type!=="DRIVE_LINK";}).length; if(used>=MSG_MAX_ATTACH)return toast(tr("Up to")+" "+MSG_MAX_ATTACH+" "+tr("attachments per message"),"bad"); var ref={type:"FILE",name:file.name||tr("Attachment"),size:(file.size/1048576).toFixed(1)+" MB",fileType:/^image\//.test(file.type)?"image":/^video\//.test(file.type)?"video":"other",mimeType:file.type||"application/octet-stream",mediaKind:msgMediaKind(file.type),preview:/^(image|video)\//.test(file.type)?URL.createObjectURL(file):"",uploadState:"pending",localFile:file}; d.refs.push(ref); CHAT_RUNTIME.focusComposer=true; renderMsgMain(true); msgUploadRef(ref,file); }
