function msgRefreshStaged(id){ var comp=document.querySelector('.msg-composer'); if(!comp||S.messageConversationId!==id) return; var d=msgDraft(id), old=comp.querySelector('.msg-staged-list'), html=d.refs.length?'<div class="msg-staged-list"><span class="tiny">'+tr("Attached to this message")+'</span>'+d.refs.map(msgStagedRefHtml).join("")+'</div>':''; if(old){ if(html) old.outerHTML=html; else old.remove(); } else if(html){ var inp=comp.querySelector('.msg-input'); if(inp) inp.insertAdjacentHTML('beforebegin',html); else comp.insertAdjacentHTML('afterbegin',html); } }
