function msgScheduleMenu(a){ var c=conv(S.messageConversationId); if(!c) return; var d=msgDraft(c.id); if(!(d.text||"").trim()&&!d.refs.length) return toast(tr("Write the message first"),"bad"); var now=new Date(), at=function(x){ return x.toISOString(); }; var h1=new Date(now.getTime()+3600e3); h1.setMinutes(0,0,0); if(h1<=now) h1=new Date(now.getTime()+3600e3); var tom=new Date(now); tom.setDate(tom.getDate()+1); tom.setHours(9,0,0,0); var mon=new Date(now); mon.setDate(mon.getDate()+((8-mon.getDay())%7||7)); mon.setHours(9,0,0,0); var fmt=function(x){ return x.toLocaleString([],{weekday:"short",hour:"2-digit",minute:"2-digit"}); }; ctxMenu(a,'<div class="mh">'+tr("Schedule message")+'</div><button onclick="closePops();msgScheduleDraft(\''+at(h1)+'\')">'+I.clock+tr("In an hour")+'<span class="hint">'+esc(fmt(h1))+'</span></button><button onclick="closePops();msgScheduleDraft(\''+at(tom)+'\')">'+I.clock+tr("Tomorrow morning")+'<span class="hint">'+esc(fmt(tom))+'</span></button><button onclick="closePops();msgScheduleDraft(\''+at(mon)+'\')">'+I.clock+tr("Next Monday")+'<span class="hint">'+esc(fmt(mon))+'</span></button><button onclick="closePops();msgScheduleCustom()">'+I.calendar+tr("Custom…")+'</button>',"left"); }
