function msgScheduleDraft(atIso){ var c=conv(S.messageConversationId); if(!c) return; if(convArchived(c)) return toast(tr("This conversation is archived"),"bad"); if(!msgCan("send_message")) return toast(tr("Your role cannot send messages"),"bad"); var m=msgBuildFromDraft(c); if(!m) return; msgScheduled().push({id:uid("sm"),conversationId:c.id,at:atIso,createdAt:new Date().toISOString(),message:m}); CHAT_RUNTIME.drafts[c.id]={text:"",refs:[],mentions:[],replyTo:null}; saveMyPrefs(); CHAT_RUNTIME.focusComposer=true; renderMsgMain(true); toast(tr("Message scheduled")+" · "+new Date(atIso).toLocaleString([],{weekday:"short",hour:"2-digit",minute:"2-digit"})); }
function msgScheduledCancel(id){ var l=msgScheduled(); var i=l.findIndex(function(x){ return x.id===id; }); if(i<0) return; var x=l.splice(i,1)[0]; saveMyPrefs(); if(S.screen==="messages") renderMsgMain(true); if(typeof undoToast==="function") undoToast("Scheduled message cancelled",function(){ msgScheduled().splice(i,0,x); saveMyPrefs(); if(S.screen==="messages") renderMsgMain(true); }); else toast(tr("Scheduled message cancelled")); }
