function msgScheduledTick(){ if(!ME||document.body.classList.contains("auth")) return; var now=Date.now(), due=msgScheduled().filter(function(x){ return !x.sentAt&&new Date(x.at).getTime()<=now; }); if(!due.length) return; due.forEach(function(x){ var l=msgScheduled(); l.splice(l.indexOf(x),1); var c=conv(x.conversationId); if(!c||convArchived(c)) return; msgPost(c,Object.assign({},x.message,{id:uid("m"),createdAt:new Date().toISOString()})); toast(tr("Scheduled message sent")+" · "+convTitle(c)); }); saveMyPrefs(); if(S.screen==="messages"){ renderMsgMain(true); renderMsgNav(); renderMsgDetail(); } messagesBadgeSync(); }
