function msgDiscard(id){ var c=conv(S.messageConversationId); if(!c) return; MESSAGES[c.id]=(MESSAGES[c.id]||[]).filter(function(x){ return x.id!==id; }); msgInvalidateDerived(c.id); msgSave(); renderMsgTimeline(true); }
