function msgOnEvent(ev){ if(ev.type==="message_created"&&ev.message){ msgIncoming(ev.message); } else if(ev.type==="typing"){ CHAT_RUNTIME.typing[ev.conversationId]=CHAT_RUNTIME.typing[ev.conversationId]||{}; CHAT_RUNTIME.typing[ev.conversationId][ev.userId]=Date.now()+4000; if(S.messageConversationId===ev.conversationId) renderMsgTimeline(true); setTimeout(function(){ if(S.screen==="messages") renderMsgTimeline(true); },4200); } else if(ev.type==="reaction_changed"||ev.type==="message_updated"||ev.type==="message_deleted"){ var l=MESSAGES[ev.conversationId]||[], m=byId(l,ev.messageId); if(m&&ev.message) Object.assign(m,ev.message); msgInvalidateDerived(ev.conversationId); if(S.messageConversationId===ev.conversationId){if(S.messageTab==="messages")renderMsgTimeline(true);else renderMsgMain(true);if(S.messageDetailTab==="shared")renderMsgDetail();} } else if(ev.type==="conversation_updated"||ev.type==="membership_changed"){ var i=CONVERSATIONS.findIndex(function(c){ return c.id===ev.conversation.id; }); if(i>=0) CONVERSATIONS[i]=Object.assign(CONVERSATIONS[i],ev.conversation); else CONVERSATIONS.push(ev.conversation); if(S.screen==="messages"){ renderMsgNav(); renderMsgDetail(); } } else if(ev.type==="presence"){ CHAT_RUNTIME.presence[ev.userId]=ev.state; if(S.screen==="messages") renderMsgNav(); } else if(ev.type==="notification_created"&&ev.notification){ NOTIFS.unshift(hNotif(ev.notification)); syncNotifDot(); renderNav(); deliverLegacyNotif(NOTIFS[0]); } }
function msgIncoming(m){ var c=conv(m.conversationId); if(!c) return; var l=MESSAGES[c.id]=MESSAGES[c.id]||[]; if(byId(l,m.id)) return; l.push(m); msgInvalidateDerived(c.id); CHAT_RUNTIME.typing[c.id]&&delete CHAT_RUNTIME.typing[c.id][m.senderId]; if(m.senderId!==ME){ var mention=msgMentionsMe(m), type=mention?"CHAT_MENTION":c.type==="DM"?"CHAT_DM":(m.replyTo&&byId(l,m.replyTo)||{}).senderId===ME?"CHAT_REPLY":c.type==="TEAM_DEFAULT"?"CHAT_TEAM_GENERAL":"CHAT_GROUP"; var preview=(m.body||"").slice(0,120)||(m.refs&&m.refs[0]?(m.refs[0].mediaKind==="IMAGE"?tr("sent a photo"):m.refs[0].mediaKind==="VIDEO"?tr("sent a video"):m.refs[0].title||m.refs[0].name||m.refs[0].fallbackTitle||tr("shared a link")):""); var res=deliverNotification({type:type,notifKey:type.toLowerCase(),priority:type==="CHAT_DM"||type==="CHAT_MENTION"?"high":type==="CHAT_TEAM_GENERAL"?"low":"medium",title:c.type==="DM"?person(m.senderId).name:person(m.senderId).name+" · "+convTitle(c)+(c.teamId?" · "+teamName(c.teamId):""),body:(mention?tr("mentioned you")+": ":"")+preview,actor:m.senderId,conversationId:c.id,messageId:m.id}); if(res&&res.inApp&&!res.push) msgToast(c,m,mention); if(mention) notifPrePrompt("mention"); }
  if(S.screen==="messages"){ if(S.messageConversationId===c.id){ if(document.visibilityState==="visible"||(typeof notifForeground==="function"&&notifForeground({conversationId:c.id}))) msgMarkRead(c,true); renderMsgTimeline(true); } renderMsgNav(); renderMsgDetail(); } messagesBadgeSync(); msgSave(); }
/* §142.3 in-app toast for a message in another conversation (shown when no browser notification was delivered): click opens it. */
function msgToast(c,m,mention){ var box=document.getElementById("toasts"); if(!box) return; var el=document.createElement("div"); el.className="toast ok msg-toast"; el.innerHTML=av(m.senderId)+'<div><b data-no-translate>'+esc(person(m.senderId).name)+(c.type==="DM"?"":' · '+esc(convTitle(c)))+'</b><span>'+(mention?tr("mentioned you")+": ":"")+esc((m.body||"").slice(0,80)||tr("shared a link"))+'</span></div>'; el.onclick=function(){ el.remove(); openConversation(c.id,m.id); }; while(box.children.length>3) box.firstChild.remove(); box.appendChild(el); setTimeout(function(){ el.style.opacity="0"; el.style.transition="opacity .25s"; setTimeout(function(){ el.remove(); },260); },5000); }
/* Demo: seed the bell with the unread chat samples so the Notification Center shows chat entries on first load, and let one unsolicited DM arrive ~20 s after Messages is first opened so badge, bell, toast and chime can be seen without a second user. */
function msgDemoSeedNotifs(){ if(API.on||CHAT_RUNTIME.seeded) return; CHAT_RUNTIME.seeded=true; if(NOTIFS.some(function(n){ return n.entityType==="message"; })) return; convVisibleList().forEach(function(c){ convUnread(c).slice(-1).forEach(function(m){ var mention=msgMentionsMe(m), k=mention?"chat_mention":c.type==="DM"?"chat_dm":c.type==="TEAM_DEFAULT"?"chat_team_general":"chat_group"; if(k==="chat_team_general"&&!mention) return; NOTIFS.push({id:uid("nt"),k:k,who:m.senderId,t:c.id,msg:m.id,text:(m.body||"").slice(0,90),ago:Math.round((Date.now()-new Date(m.createdAt))/60000),read:false,entityType:"message"}); }); }); NOTIFS.sort(function(a,b){ return (a.ago||0)-(b.ago||0); }); syncNotifDot(); }
function msgDemoIncoming(){ if(API.on||CHAT_RUNTIME.demoIncoming) return; CHAT_RUNTIME.demoIncoming=true; setTimeout(function(){ var c=conv("cv_dm_zein_maya")||CONVERSATIONS.filter(function(x){ return x.type==="DM"&&convMember(x); })[0]; if(!c) return; var who=convPeer(c); msgIncoming({id:uid("m"),conversationId:c.id,senderId:who,type:"TEXT",body:UI_LANG==="id"?"Zein, copy final untuk hero HSB Pro 2.0 sudah aku taruh di Drive. Bisa dicek?":"Zein, the final hero copy for HSB Pro 2.0 is in Drive. Can you check?",mentions:[],refs:[{type:"TASK",entityId:"T-118",fallbackTitle:"HSB Pro 2.0 — hero banner"}],replyTo:null,reactions:{},createdAt:new Date().toISOString(),_local:true}); },20000); }
/* Standalone demo realtime: a member of the conversation replies after a
   short typing delay so notifications, sound and unread state can be tried
   without a server. Nothing here runs in API mode. */
var MSG_SIM_REPLIES=["Noted, thanks!","Oke, aku cek dulu ya.","👍","Bisa. Aku update di task-nya nanti sore.","Got it — will share the revision here.","Siap, nanti aku follow up.","Makes sense. Let's go with that.","Nice, kirim ke #design juga ya."];
function msgSimulateReply(c,m){ var others=convMembers(c).filter(function(id){ return id!==ME&&!person(id).stakeholder; }); if(!others.length) return; var who=(m.mentions||[]).map(function(x){ return x.userId; }).filter(function(id){ return others.indexOf(id)>=0; })[0]||others[Math.floor(Math.random()*others.length)]; CHAT_RUNTIME.sim[c.id]&&clearTimeout(CHAT_RUNTIME.sim[c.id]); setTimeout(function(){ CHAT_RUNTIME.typing[c.id]=CHAT_RUNTIME.typing[c.id]||{}; CHAT_RUNTIME.typing[c.id][who]=Date.now()+4000; if(S.screen==="messages"&&S.messageConversationId===c.id) renderMsgTimeline(true); },1200); CHAT_RUNTIME.sim[c.id]=setTimeout(function(){ var body=MSG_SIM_REPLIES[Math.floor(Math.random()*MSG_SIM_REPLIES.length)]; if(/\?/.test(m.body)) body=first(who)==="Sarah"?"Yes — I can start on it after lunch.":"Ya, bisa. Aku info kalau sudah."; msgIncoming({id:uid("m"),conversationId:c.id,senderId:who,type:"TEXT",body:body,mentions:[],refs:[],replyTo:m.id,reactions:{},createdAt:new Date().toISOString(),_local:true}); },3600); }
/* deep links: #conv=…&msg=… (from notifications / copied links) */
function msgHandleHash(){ var h=location.hash||""; var mc=h.match(/conv=([-\w]+)/), mm=h.match(/msg=([-\w]+)/); if(mc){ history.replaceState(null,"",location.pathname+location.search); msgLoad().then(function(){ openConversation(mc[1],mm?mm[1]:null); }); return true; } return false; }
/* Called from applyShell(): (re)load the conversation summary for the signed-in member so the topbar badge is right before Messages is ever opened. */
function msgBootSync(){ if(CHAT_RUNTIME.forUser!==ME||CHAT_RUNTIME.forWs!==WS.id){ CHAT_RUNTIME.forUser=ME; CHAT_RUNTIME.forWs=WS.id; CHAT_RUNTIME.loaded=false; CHAT_RUNTIME.drafts={}; if(CHAT_RUNTIME.connection){ try{ CHAT_RUNTIME.connection.close(); }catch(e){} CHAT_RUNTIME.connection=null; } if(document.body.classList.contains("auth")) return; msgLoad().then(function(){ messagesBadgeSync(); if(!msgHandleHash()&&S.screen==="messages") renderMessages(); }); } else messagesBadgeSync(); }
document.addEventListener("visibilitychange",function(){ if(document.visibilityState==="visible"&&S.screen==="messages"&&S.messageConversationId){ var c=conv(S.messageConversationId); if(c) msgMarkRead(c); } });
